mapper.insert:
insert into fangjian_xinxi (
    loudong, louceng, fangjianhao, fangjian_leixing, chuangwei_shu, chaoxiang, tupian, zhuangtai, beizhu
) values (
    coalesce(#{loudong}, '606号楼'), #{louceng}, #{fangjianhao}, #{fangjianLeixing}, coalesce(#{chuangweiShu}, 0),
    #{chaoxiang}, coalesce(#{tupian}, '/uploads/environment/room-default.jpg'), coalesce(#{zhuangtai}, '正常'), #{beizhu}
)

mapper.update:
update fangjian_xinxi
set zhuangtai = '已删除'
where id = #{id}

mapper.select:
select c.id, c.fangjian_id as fangjianId, f.fangjianhao, f.louceng, c.chuangweihao, c.zhuangtai from chuangwei_xinxi c join fangjian_xinxi f on c.fangjian_id = f.id where c.zhuangtai = '空闲' and coalesce(c.shanchu_zhuangtai, '正常') = '正常' and f.zhuangtai != '已删除'
and c.fangjian_id = #{fangjianId}
order by f.louceng, f.fangjianhao, c.chuangweihao

mapper.insert:
insert into chuangwei_xinxi (
    fangjian_id, chuangweihao, zhuangtai, chuangwei_tupian, beizhu, shanchu_zhuangtai
) values (
    #{fangjianId}, #{chuangweihao}, coalesce(#{zhuangtai}, '空闲'),
    coalesce(#{chuangweiTupian}, '/uploads/environment/bed-default.jpg'), #{beizhu}, '正常'
)

mapper.update:
update chuangwei_xinxi
set shanchu_zhuangtai = '已删除'
where id = #{id}

update fangjian_xinxi
set chuangwei_shu = (
    select count(1)
    from chuangwei_xinxi
    where fangjian_id = #{fangjianId}
      and coalesce(shanchu_zhuangtai, '正常') = '正常'
)
where id = #{fangjianId}

mapper.insert:
insert into chuangwei_shiyong (
    laoren_id, fangjian_id, chuangwei_id, kaishi_riqi, shiyong_zhuangtai, yuanyin
) values (
    #{laorenId}, #{fangjianId}, #{chuangweiId}, coalesce(#{kaishiRiqi}, curdate()), '正在使用', #{yuanyin}
)

mapper.update:
update chuangwei_shiyong
set shiyong_zhuangtai = '历史',
    jieshu_riqi = curdate(),
    yuanyin = #{yuanyin}
where laoren_id = #{laorenId}
  and shiyong_zhuangtai = '正在使用'
